import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '../../components/common/ui';
import type { OrientationResult } from '../../types/api';

/** Readable case summary generated by the API from structured data (no AI). Can be copied or printed for the doctor. */
export function CaseSummary({ summary }: { summary: OrientationResult['case_summary'] }) {
  const { t } = useTranslation();
  const [copied, setCopied] = useState(false);

  async function copy() {
    try {
      await navigator.clipboard.writeText(summary.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  }

  return (
    <section aria-labelledby="case-summary-title" className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-brand-200 sm:p-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 id="case-summary-title" className="text-lg font-semibold text-slate-900">{t('summary.title')}</h2>
          <p className="text-sm text-slate-500">{t('summary.subtitle')}</p>
        </div>
        <div className="no-print flex gap-2">
          <Button variant="secondary" onClick={copy}>{copied ? t('summary.copied') : t('summary.copy')}</Button>
          <Button variant="secondary" onClick={() => window.print()}>{t('summary.print')}</Button>
        </div>
      </div>
      <div className="mt-4 space-y-3 text-[15px] leading-relaxed text-slate-800">
        {summary.paragraphs.map((p, i) => (
          <p key={i} className={i === summary.paragraphs.length - 1 ? 'text-sm text-slate-500' : undefined}>{p}</p>
        ))}
      </div>
    </section>
  );
}
